export type Asset = {
	/**  Unique within the project, derived from the name. */
	id: string,
	name: string,
	kind: AssetKind,
	stage: Stage,
	status: AssetStatus,
	/**  Oldest first. */
	versions: AssetVersion[],
	/**  Relative to the project folder, with `/` separators. */
	thumbnail: string | null,
	createdAt: string,
	updatedAt: string,
	/**
	 *  The library entry and version this asset was copied from, when it
	 *  came from the library. The project owns its copy either way; the
	 *  origin only says where to look for an update. Older files have none.
	 */
	origin?: AssetOrigin | null,
	/**
	 *  Its refs and the view each shows, once someone tagged them. Empty
	 *  for an asset nobody tagged: its views follow its refs' order then
	 *  (see [`crate::refs`]).
	 */
	refs?: AssetRef[],
};

export type AssetKind = "prop" | "character" | "scene";

/**
 *  Where a Board asset came from in the library: the entry id and the
 *  library version its newest model is.
 */
export type AssetOrigin = {
	entry: string,
	version: number,
};

/**  One asset's parts as its newest model ships them. */
export type AssetParts = {
	project: string,
	asset: string,
	name: string,
	kind: AssetKind,
	/**  The newest version, when the asset has a model. */
	version: number | null,
	/**
	 *  The file the parts were read from, an absolute path: the newest
	 *  model, or the fix-up preview's copy once a split ran.
	 */
	file: string | null,
	/**  Its fix-ups cut or join the parts. */
	split: boolean,
	/**  They do, and the preview that lists the parts has not run yet. */
	needsPreview: boolean,
	rows: PartRow[],
	plan: PartsPlan,
	/**  A game project: no Timeline, so Compare explodes the parts itself. */
	game: boolean,
};

/**  One asset's real size and fix-ups, with what its newest model measures. */
export type AssetPrep = {
	project: string,
	asset: string,
	name: string,
	kind: AssetKind,
	entry: ModelPrep,
	/**  The newest version, when the asset has a model. */
	version: number | null,
	/**  Width, height and depth of that model as it came, metres. */
	measured: [(number | null), (number | null), (number | null)] | null,
	/**  The same after the fix-ups, once a preview of them ran. */
	fixed: [(number | null), (number | null), (number | null)] | null,
	/**  The real size scale on the fixed (else measured) model. */
	scale: number | null,
	/**  A size from the name and kind, never applied on its own. */
	suggestion: Suggestion | null,
	/**  The last preview of the entry on the newest model, when one ran. */
	report: FixupReport | null,
	defaults: FixupDefaults,
};

/**  One ref of an asset and the view it shows. */
