export type AssetShip_Serialize = {
	choice: ShipChoice,
	/**  The stem the model ships as, without `.glb`. */
	file?: string | null,
};

/**  Mirrors the kit's status chips. */
export type AssetStatus = "done" | "cached" | "running" | "failed" | "review" | "queued";

export type AssetVersion = {
	version: number,
	/**  Relative to the project folder, with `/` separators. */
	file: string,
	createdAt: string,
	stats: ModelStats | null,
};

/**  What a remove did, with the project as it is now. */
export type AssetsRemoved = {
	project: ProjectManifest,
	/**  One per asset asked for, in the order asked. */
	outcomes: RemoveOutcome[],
};

/**  What a build did. */
export type AvatarBuild = 
/**
 *  The weights that free cloth and hair from the arms wait for a person
 *  to look at the sheets; the rest pose comes after.
 */
{ status: "reweight waiting for approval"; reweighted: Reweighted } | 
/**  The new rest pose waits for a person to look at the sheets. */
{ status: "waiting for approval"; normalized: Normalized } | 
/**  A person turned the new rest pose down. */
{ status: "denied"; normalized: Normalized } | 
/**
 *  The chains of the confirmed springs wait for a person to look at
 *  the sway sheets. `carried` names the picks carried over to the
 *  parts the finder sees now, when the model changed under them.
 */
{ status: "springs waiting for approval"; chained: Chained; carried: SpringCarried[] } | 
/**
 *  Nobody picked springs yet, the last export carried some and the
 *  finder proposes parts: they wait for a pick (or for none to be
 *  confirmed), and nothing is written.
 */
{ status: "candidates waiting for a pick"; found: FoundSprings } | 
/**
 *  The confirmed springs no longer match the parts the finder sees on
 *  this model (`stale`, by id): pick again. Nothing is written.
 */
{ status: "springs no longer match"; found: FoundSprings; stale: string[] } | 
/**  The `.vrm` is written. */
{ status: "written"; export: AvatarExport; normalized: Normalized | null };

/**
 *  An agent changed or built an asset's avatar through the MCP server, so
 *  the Avatar view reloads it.
 */
export type AvatarChanged = {
	project: string,
	asset: string,
};

/**  What a new avatar spec starts from. */
export type AvatarDefaults = {
	/**  The author every avatar names first; empty leaves it to fill in. */
	author?: string,
	contactInformation?: string | null,
	copyrightInformation?: string | null,
	avatarPermission?: AvatarPermission,
	commercialUsage?: CommercialUsage,
	creditNotation?: CreditNotation,
	modification?: Modification,
	allowRedistribution?: boolean,
	allowExcessivelyViolentUsage?: boolean,
	allowExcessivelySexualUsage?: boolean,
	allowPoliticalOrReligiousUsage?: boolean,
	allowAntisocialOrHateUsage?: boolean,
	otherLicenseUrl?: string | null,
	material?: MaterialMode,
};

/**  What the last build wrote. */
export type AvatarExport = {
	/**  The `.vrm`, an absolute path. */
	path: string,
	bytes: number | null,
	sourceVersion: number,
	/**  Written from a normalised rest pose (else from the model as it is). */
	normalized: boolean,
	/**
	 *  The arms were lifted from an approved reweight that freed cloth and
	 *  hair from them. False for a build that predates the reweight.
	 */
	reweighted?: boolean,
	material: MaterialMode,
	/**
	 *  With MToon, what was done with the highlights baked into the base
	 *  color; `None` with PBR or for a build that predates the option.
	 *  Boxed, so a written build stays near the size of the others.
	 */
	highlights?: HighlightsReport | null,
	/**  What the file still lacks, blockers first. */
	unresolved: VrmFinding[],
	writtenAt: string,
	/**  The file is still there. Read, never stored. */
	exists?: boolean,
	/**
	 *  The validation report beside the file, an absolute path; `None`
	 *  when it is gone or the build predates it.
	 */
	report?: string | null,
	/**
	 *  The written bytes read back and checked; `None` for a build that
	 *  predates the check.
	 */
	roundTrip?: RoundTrip | null,
	/**  The springs the file carries; 0 for a build that predates them. */
	springs?: number,
};

