/**  Never built. */
"new" | 
/**  The newest version comes from these exact files. */
"current" | 
/**  The script, a helper or the root changed since the last build. */
"stale" | 
/**  The last build of these exact files failed. */
"failed" | 
/**  The script or a helper is gone from `built/`. */
"missing" | 
/**  Building now. */
"building";

